package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamBotanyBank2 {
  private const val T = "ශාක ක්‍රියාකාරීත්වය, ප්‍රභාසංස්ලේෂණය හා පරිවහනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ශාක ජීව විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පත්‍ර රන්ධ්‍ර දිවා කාලයේදී විවෘතව පැවතීමට හේතු වන ප්‍රධාන වායු හුවමාරු අවශ්‍යතාව කුමක්ද?", "ප්‍රභාසංස්ලේෂණය සඳහා CO₂ ඇතුළු කර ගැනීම", "පසෙන් ජලය පිට කිරීම", "නයිට්‍රජන් අවශෝෂණය", "පිෂ්ඨය පිට කිරීම", "දිවා කාලයේදී ආලෝකය හමුවේ CO₂ ඇතුළු වීම අවශ්‍ය වේ."),
    q("ශාක පත්‍රයක පාලක සෛල තුළ අඩංගු වන නමුත් අනෙකුත් අපිචර්ම සෛලවල නොමැති ඉන්ද්‍රයිකාව කුමක්ද?", "හරිතලවය", "න්‍යෂ්ටිය", "මයිටොකොන්ඩ්‍රියාව", "රික්තකය", "පාලක සෛලවල ඇති හරිතලව මඟින් දිවා කාලයේදී සීනි සාදයි."),
    q("අල, බතල සහ මඤ්ඤොක්කා වැනි ශාකවල ආහාර ගබඩා වී ඇති භූගත ව්‍යුහ මොනවාද?", "ආකන්ද (අල)", "ධාවක", "මෝරියන්", "ප්‍රකන්ද", "අර්තාපල් යනු භූගත කඳක් වන අතර බතල යනු ආකන්ද මුලකි."),
    q("ගොටුකොළ හා උඳුපියලිය වැනි ශාක ස්වාභාවිකව වර්ධක ප්‍රචාරණය සිදු කරන කඳ වර්ගය කුමක්ද?", "ධාවක (Runners)", "බල්බ", "කෝම", "ප්‍රකන්ද", "ධාවක කඳන් පොළොව මතුපිටින් තිරස්ව වැඩෙමින් ගැටවලින් මුල් අදී."),
    q("රතු ලූනු සහ සුදු ලූනු ශාකවල ප්‍රචාරණය සිදු වන භූගත කඳ වර්ගය කුමක්ද?", "බල්බ", "ප්‍රකන්ද", "කෝම", "ධාවක", "බල්බයක මාංසල ශල්ක පත්‍රවල ආහාර ගබඩා වේ."),
    q("ඉඟුරු සහ කහ ශාකවල භූගතව තිරස්ව වැඩෙන ආහාර සංචිත කඳ වර්ගය කුමක්ද?", "ප්‍රකන්ද (Rhizomes)", "බල්බ", "අල", "ධාවක", "ප්‍රකන්දවල පර්ව හා ගැට පිහිටා ඇත."),
    q("අක්කපාන ශාකය ස්වාභාවිකව නව පැළ බිහි කරන්නේ ශාකයේ කුමන කොටසෙන්ද?", "පත්‍ර දාරවලින්", "මුල්වලින්", "කඳේ අග්‍රයෙන්", "පරාගවලින්", "අක්කපාන පත්‍ර දාරවල පිහිටි අංකුරවලින් නව පැළ හටගනී."),
    q("දෙල් සහ කරපිංචා ශාකවල බහුලව නව පැළ ලබා ගත හැකි වර්ධක ප්‍රචාරණ ව්‍යුහය කුමක්ද?", "මුල්වලින් හටගන්නා අංකුර", "පත්‍ර අංකුර", "බල්බ", "ප්‍රකන්ද", "මුල් කැබලිවලින් මූල අංකුර හටගනී."),
    q("වී ඇටයක් (ඒකබීජ පත්‍රී) ප්‍රරෝහණය වීමේදී මුලින්ම ආහාර සැපයෙන ප්‍රධාන පටකය කුමක්ද?", "භ්‍රෑණ පෝෂය (Endosperm)", "බීජාවරණය", "ප්‍රරෝහ කොපුව", "මූලාංකුරය", "මෑ වැනි ද්විබීජ පත්‍රී බීජවල ආහාර බීජ පත්‍රවල ගබඩා වේ."),
    q("බීජ පැළ වීමේදී පොළොවට ඉහළින් ඇති ආලෝකය ලබා නොගත් කුඩා කාලයේ පෝෂණය ලබා ගන්නේ කෙසේද?", "බීජයේ සංචිත ආහාර ශ්වසනය කිරීමෙන්", "ප්‍රභාසංස්ලේෂණයෙන්", "පසෙන් පිෂ්ඨය උරා ගැනීමෙන්", "වායුවෙන් ග්ලූකෝස් ගැනීමෙන්", "පළමු කොළ පත්‍ර විවෘත වන තෙක් සංචිත ආහාර භාවිත වේ."),
    q("බීජ සුප්තතාව (Dormancy) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "හිතකර සාධක තිබුණද බීජ ප්‍රරෝහණය නොවීම", "අහිතකර තත්ත්ව හමුවේ බීජ මිය යාම", "ජලයේ පාවී ගොස් විනාශ වී යාම", "දිලීර ආසාදනයෙන් බීජ කුණු වීම", "සුප්තතාව බීජ අහිතකර කාලගුණයෙන් ආරක්ෂා කිරීමට උපකාරී වේ."),
    q("බඩඉරිඟු හා තණකොළ වැනි පුෂ්පවල දැකිය හැකි වර්ණයෙන් අඩු මණි හා දළ පත්‍ර වෙනුවට ඇති ව්‍යුහය කුමක්ද?", "තුෂ", "කෙඳි", "මධු කෝෂ", "අතිපත්‍ර", "සුළඟින් පරාගණය වන ශාකවල ආකර්ෂණීය දළ පත්‍ර අනවශ්‍ය වේ."),
    q("පරාග කලංකය මත තැන්පත් වූ පසු ඩිම්බය වෙත පුරුෂ ජන්මාණු ගෙන යන ව්‍යුහය කුමක්ද?", "පරාග නාලය", "කීලය", "සූත්‍රිකාව", "බීජ නාලය", "පරාග කණිකාව කලංකයේ සීනි ද්‍රාවණයේ ප්‍රරෝහණය වී පරාග නාලය සාදයි."),
    q("රබර්, බණ්ඩක්කා හා කූඩලු වැනි ශාකවල ඵල වියළී පුපුරා යාමෙන් බීජ විසිරී යන ක්‍රමය කුමක්ද?", "ස්ඵෝටනය", "ජල ප්‍රවාහනය", "වායු ප්‍රවාහනය", "සත්ව ප්‍රවාහනය", "පීඩනය වැඩි වී ඵලාවරණය පුපුරා බීජ ඈතට විසි වේ."),
    q("දොඩම් හා අඹ වැනි බීජ රහිත පළතුරු වර්ග (අනිෂේක ඵල) නිපදවීමට කෘත්‍රිමව යොදන හෝමෝනය කුමක්ද?", "ඔක්සීන් හෝ ජිබරලීන්", "ඇබ්සිසික් අම්ලය", "එතිලීන්", "තයිරොක්සින්", "සංසේචනයකින් තොරව ඩිම්බකෝෂය ඵලයක් බවට පත් වීම අනිෂේක ඵලතාවයි."),
    q("ශාක පත්‍ර හා ඵල වයස්ගත වී ගසෙන් ගිලිහී වැටීම (Abscission) පාලනය කරන හෝමෝනය කුමක්ද?", "ඇබ්සිසික් අම්ලය හා එතිලීන්", "ජිබරලීන්", "සයිටොකයිනින්", "ඇඩ්‍රිනලින්", "ජල හිඟ කාලවලදී ඇබ්සිසික් අම්ලය රන්ධ්‍ර වැසීමට ද දායක වේ."),
    q("ශාකයක සෛල විභාජනය වේගවත් කරන සහ පත්‍ර කල් තබා ගැනීමට උපකාරී වන හෝමෝනය කුමක්ද?", "සයිටොකයිනින්", "ඇබ්සිසික් අම්ලය", "එතිලීන්", "පෙප්සින්", "සයිටොකයිනින් ප්‍රධාන වශයෙන් මුල් අග්‍රවල නිපදවේ."),
    q("ශාක කඳන්වල පර්ව දික් කිරීමට හා කුරු ශාක උස් කිරීමට බලපාන ශාක හෝමෝනය කුමක්ද?", "ජිබරලීන්", "ඇබ්සිසික් අම්ලය", "එතිලීන්", "ලැක්ටේස්", "ජිබරලීන් බීජ සුප්තතාව බිඳීමට ද උපකාරී වේ."),
    q("විදුලි ලාම්පුවක් අසල තැබූ පැළෑටියක කඳ ආලෝකය දෙසට නැමී වර්ධනය වීමට හේතුව කුමක්ද?", "අඳුරු පැත්තේ ඔක්සීන් වැඩි වී සෛල වේගයෙන් දික් වීම", "ආලෝක පැත්තේ සෛල මැරී යාම", "ආලෝකය කඳ ඇද ගැනීම", "පත්‍රවල බර වැඩි වීම", "ඔක්සීන් අසමමිතික ව්‍යාප්තිය ධන ප්‍රකාශවර්තනය ඇති කරයි."),
    q("මුලක අග්‍රයේ ආරක්ෂාව සඳහා පිහිටි ආවරණ ව්‍යුහය කුමක්ද?", "මූල කොපුව (Root cap)", "මූල කේශය", "විභාජක කලාපය", "පටක ආවරණය", "පස හරහා මුල ගමන් කරන විට මූල අග්‍රයට වන හානි මූල කොපුව වළක්වයි."),
    q("පොටෝමීටර පරීක්ෂණයේදී ශාක අත්ත ජලය යටදී ඇලයට කපා සවි කරන්නේ ඇයි?", "සෛලම නාලවලට වායු බුබුළු ඇතුළු වීම වැළැක්වීමට", "ජලය වාෂ්ප වීම වැඩි කිරීමට", "මුල් ඇදීම ඉක්මන් කිරීමට", "අත්ත පාවීම වැළැක්වීමට", "වායු බුබුළු ඇතුළු වුවහොත් ජල කඳ බිඳී උත්ස්වේදනය නවතී."),
    q("ශාකයක ජලය පරිවහනය වන සෛලම නාලවල රතු ඊයෝසින් (Eosin) ද්‍රාවණය යොදා කරන පරීක්ෂණයෙන් පෙනී යන්නේ කුමක්ද?", "සෛලම පටකය පමණක් රතු පැහැ ගැන්වීම", "ෆ්ලෝයමය පමණක් රතු වීම", "මුළු කඳම කළු පැහැ වීම", "පත්‍ර හැලී යාම", "ජලය හා ද්‍රාවණ ඉහළට ගමන් කරන්නේ සෛලම හරහා බව ඉන් තහවුරු වේ."),
    q("ශාක තුළ දිවා කාලයේදී ශ්වසනය සිදුවේද?", "ඔව්, ශාක සෑම විටම ශ්වසනය සිදු කරයි", "නැත, රාත්‍රියේදී පමණි", "නැත, ප්‍රභාසංස්ලේෂණය පමණි", "මුල්වල පමණක් දිවා කාලයේ සිදුවේ", "දිවා කාලයේ ප්‍රභාසංස්ලේෂණ සීඝ්‍රතාව ශ්වසනයට වඩා වැඩි නිසා O₂ පිටවේ."),
    q("අඳුරු කාමරයක විසිතුරු ශාක රාශියක් රාත්‍රියේ තැබීම නුසුදුසු යැයි පවසන්නේ ඇයි?", "රාත්‍රියේ ප්‍රභාසංස්ලේෂණය නැති නිසා O₂ උරාගෙන CO₂ පිට කිරීම", "ශාක විෂ වායු නිපදවීම", "ශාකවල උෂ්ණත්වය ඉහළ යාම", "ආර්ද්‍රතාව ශුන්‍ය වීම", "රාත්‍රියේදී සියලු ශාක ශ්වසනයෙන් CO₂ පිට කරයි."),
    q("පත්‍රයක් තුළ ප්‍රභාසංස්ලේෂණය සිදුවීමේදී CO₂ වායුව සෛල වෙත ළඟා වීමට උපකාරී වන පත්‍ර ව්‍යුහය කුමක්ද?", "අන්තර් සෛලීය අවකාශ", "ජලයට අපාරගම්‍ය උච්චර්මය", "යාන්ත්‍රික දෘඪස්තර තන්තු", "ෆ්ලෝයමයේ පෙනේර තැටි", "විශාල වායු අවකාශ වායු විසරණය පහසු කරයි."),
    q("වැසි සමයේදී තෙතමනය අධික වුවද පොල් වැනි ශාකවල පස ජලයෙන් යට වුවහොත් මුල් කුණු වීමට හේතුව කුමක්ද?", "මුල්වල ශ්වසනයට පසෙහි ඔක්සිජන් හිඟ වීම", "පසේ CO₂ සම්පූර්ණයෙන් නැති වීම", "හිරු එළිය නොලැබීම", "වැසි ජලය අම්ල වීම", "මූල සෛලවල සක්‍රිය ඛනිජ අවශෝෂණයට ශ්වසන ශක්තිය අවශ්‍ය වේ."),
    q("ගොවීන් වගා බිම්වල වල් පැළෑටි මර්දනය කිරීමට යොදාගන්නා කෘත්‍රිම ශාක හෝමෝන විශේෂය කුමක්ද?", "සංශ්ලේෂිත ඔක්සීන හෝමෝන", "ස්වාභාවික ජිබරලීන් හෝමෝන", "සෛල විභාජන සයිටොකයිනින්", "ඇබ්සිසික් අම්ල සංයෝග", "සංශ්ලේෂිත ඔක්සීන පළල් පත්‍ර සහිත වල් පැළෑටි පාලනයට යොදා ගනී."),
    q("ශාක පත්‍රයක නිපදවුණු අතිරික්ත ග්ලූකෝස් දිවා කාලයේදී තාවකාලිකව පත්‍රය තුළ තැන්පත් කෙරෙන්නේ කුමන ආකාරයටද?", "පිෂ්ඨ කණිකා ලෙස", "තෙල් බිංදු ලෙස", "සුක්‍රෝස් ස්ඵටික ලෙස", "සෙලියුලෝස් ලෙස", "රාත්‍රී කාලයේදී මෙම පිෂ්ඨය සුක්‍රෝස් බවට හැරී පරිවහනය වේ."),
    q("ශාකයක කඳෙන් හා පත්‍රවලින් ජලය ඉවත් වීමේදී පළමුවෙන් ජලය වාෂ්ප වන්නේ කොතැනින්ද?", "මධ්‍යස්තර සෛල බිත්ති මතුපිටින්", "මූල කේශවලින්", "කැම්බියමෙන්", "සෛලම භ්‍රෑණයෙන්", "මධ්‍යස්තර සෛලවලින් වාෂ්ප වී රන්ධ්‍ර හරහා පිටතට විසරණය වේ."),
    q("ශාක අංකුර හෝ බද්ධ කොටස් රෝග කාරකයන්ගෙන් තොරව පරීක්ෂණාගාරයක් තුළ කෘත්‍රිම රෝපණ මාධ්‍යයක වගා කිරීම කුමක්ද?", "පටක රෝපණය", "බද්ධ කිරීම", "අතු බැඳීම", "විකිරණ ප්‍රතිකාරය", "මෙහිදී MS රෝපණ මාධ්‍යය භාවිත කෙරේ."),
    q("රසායනාගාරයේදී පැළෑටියක ආලෝක තීව්‍රතාව ප්‍රභාසංස්ලේෂණයට බලපාන ආකාරය සෙවීමේදී මනිනු ලබන්නේ කුමක්ද?", "පිටවන ඔක්සිජන් බුබුළු සංඛ්‍යාව", "පත්‍රයේ හරස්කඩ ඝනකම මැනීම", "මුල් පද්ධතියේ බර මැනීම", "ශාක කඳේ උස හා දිග මැනීම", "ආලෝක ප්‍රභවය ළං කරන විට බුබුළු පිටවන සීඝ්‍රතාව වැඩි වේ."),
    q("අභිජනනය මඟින් නව බෝග ප්‍රභේද බිහි කිරීමේදී මිනිසා විසින් එක් පුෂ්පයක පරාග තවත් ශාකයක පුෂ්ප කලංකයේ තැන්පත් කිරීම කුමක්ද?", "කෘත්‍රිම පරාගණය", "ස්ව-පරාගණය", "අනිෂේක ඵලතාව", "වර්ධක ප්‍රචාරණය", "ඉහළ අස්වැන්නක් හා රෝග ප්‍රතිරෝධීතාව ලබා ගැනීමට මෙය යොදා ගනී."),
    q("ශාක පත්‍රයක පහළ කොටසේ ඇති පත්‍ර වෘන්තය (Petiole) මඟින් ඉටු කරන ප්‍රධාන කාර්යය කුමක්ද?", "ආලෝකය ලැබෙන සේ පත්‍රය රඳවා තැබීම", "පසෙන් ජලය හා ඛනිජ උරා ගැනීම", "පරාග නිපදවා පරාගණය සිදු කිරීම", "බීජ ආරක්ෂා කරමින් පෝෂණය කිරීම", "පත්‍ර වෘන්තය තුළින් සනාල කලාප පත්‍ර තලයට ඇතුළු වේ."),
    q("රබර් ගසින් කිරි (ලේටෙක්ස්) ලබා ගැනීමේදී පොත්ත කපා ඉවත් කරන්නේ ගසේ කුමන ස්තරයට නොපැමිණෙන ලෙසද?", "කැම්බියම් ස්තරයට", "බාහිර පොත්තට", "මෘදුස්තරයට", "අපිචර්මයට", "කැම්බියමට හානි වුවහොත් පොත්ත නැවත අලුතින් වර්ධනය නොවේ."),
    q("ශාකවල ශීත ඍතුවේදී හෝ නියඟයේදී පත්‍ර හැලී යාමෙන් සිදුවන ප්‍රධාන වාසිය කුමක්ද?", "උත්ස්වේදනයෙන් වන ජල හානිය අවම වීම", "ප්‍රභාසංස්ලේෂණය විශාල ලෙස වැඩි වීම", "ශාකයේ කඳ ඉක්මනින් මහත් වීම", "අලුත් මල් හට ගැනීම උත්තේජනය වීම", "පත්‍ර හැලීම ජල සංරක්ෂණ ක්‍රමයකි."),
    q("දේහයේ හරිතප්‍රද නොමැති නිසා වෙනත් ශාක කඳන් මත මූල පද්ධති යවා ආහාර හා ජලය උරා ගන්නා පූර්ණ පරපෝෂී ශාකය කුමක්ද?", "කස්කුටා (අගමුල නැති වැල)", "ලොරැන්තස් (පිළිල)", "ඕකිඩ්", "මීවන", "කස්කුටා කහ පැහැති සම්පූර්ණ පරපෝෂී ශාකයකි."),
    q("කොළ පැහැති පත්‍ර ඇති නිසා ප්‍රභාසංස්ලේෂණය කළද ධාරක ශාකයෙන් ජලය හා ඛනිජ උරා ගන්නා අර්ධ පරපෝෂී ශාකය කුමක්ද?", "පිළිල (Loranthus)", "කස්කුටා", "බිම්මල්", "නෙෆ්‍රොලෙපිස්", "පිළිල ගස්වල අතු මත වැඩෙමින් ජලය හා ඛනිජ ලබා ගනී."),
    q("ශාක කඳ මත ආධාරකයකින් ආහාර නොගෙන රැඳී සිටින අපිශාකයකට උදාහරණයක් වන්නේ කුමක්ද?", "උඩවැඩියා (ඕකිඩ්)", "පිළිල", "කස්කුටා", "මහෝගනී", "උඩවැඩියා ශාක වායව මුල් මඟින් වාතයේ තෙතමනය උරා ගනී."),
    q("බාඳුරා වැනි කෘමි භක්ෂක ශාක කෘමීන් අල්ලා ජීර්ණය කිරීමෙන් ප්‍රධාන වශයෙන් ලබා ගන්නා මූලද්‍රව්‍යය කුමක්ද?", "නයිට්‍රජන්", "කැල්සියම්", "කාබන්", "මැග්නීසියම්", "නයිට්‍රජන් හිඟ වගුරු පස්වල වැඩෙන බැවින් කෘමි ප්‍රෝටීන ජීර්ණය කරයි."),
    q("ශාක සෛලවල ප්‍රභාසංස්ලේෂණයේ 'අඳුරු ප්‍රතික්‍රියාව' හෙවත් කැල්වින් චක්‍රය සිදුවන්නේ හරිතලවයේ කුමන කොටසේද?", "ස්ට්‍රෝමාව (Stroma)", "තයිලකොයිඩ පටලය", "න්‍යෂ්ටිය", "රයිබොසෝමය", "ආලෝක ප්‍රතික්‍රියාව ග්‍රැනාවල ද අඳුරු ප්‍රතික්‍රියාව ස්ට්‍රෝමාවේ ද සිදුවේ."),
    q("ශාක කඳන්වල උත්ස්වේදනය සුළු ප්‍රමාණයකින් හෝ වායු හුවමාරුව ප්‍රධාන වශයෙන් සිදුවන කාෂ්ඨීය කඳේ සිදුරු මොනවාද?", "වා සිදුරු (Lenticels)", "පත්‍ර රන්ධ්‍ර", "ජල රන්ධ්‍ර", "ප්ලාස්ම බන්ධ", "පැරණි කාෂ්ඨීය කඳන්වල පොත්ත මත වා සිදුරු පිහිටයි."),
    q("ද්විබීජ පත්‍රී ශාක මුලක හරස්කඩක සෛලම පටකය දිස්වන්නේ කුමන හැඩයෙන්ද?", "තරු හැඩැති මධ්‍යස්ථානයක් ලෙස", "වළලු රාශියක් ලෙස", "පිටත අපිචර්මයේ ලප ලෙස", "විසිරුණු කලාප ලෙස", "ඒකබීජ පත්‍රී මුලක මැද විශාල මජ්ජාවක් වටා වළල්ලක් ලෙස සෛලම පිහිටයි."),
    q("ජලාශයක පාවී වැඩෙන ශාකයක පත්‍ර රන්ධ්‍ර බහුලව පිහිටන්නේ කුමන පෘෂ්ඨයේද?", "උඩු පෘෂ්ඨයේ", "යටි පෘෂ්ඨයේ", "මුල්වල", "කඳේ අභ්‍යන්තරයේ", "නෙළුම් හා ඕලු පත්‍රවල යටි පැත්ත ජලය ස්පර්ශ කරන නිසා උඩු පැත්තේ රන්ධ්‍ර පිහිටයි."),
    q("ජලයේ සම්පූර්ණයෙන් ගිලී වැඩෙන ජලජ ශාක (උදා: හයිඩ්‍රිල්ලා) වල බොහෝ විට නොමැති පත්‍ර ලක්ෂණය කුමක්ද?", "ඝන ඉටි උච්චර්මය සහ රන්ධ්‍ර", "හරිතලව", "ප්ලාස්ම පටල", "න්‍යෂ්ටි", "ජලය හා වායූන් සෘජුව අපිචර්මය හරහා විසරණය වේ."),
    q("ගොයම් ගොවිතැනේදී කරල් පීදීමේදී පරාගණය සාර්ථක වීමට බලපාන ප්‍රධාන ස්වාභාවික කාරකය කුමක්ද?", "සුළඟ", "මීමැස්සන්", "කුරුල්ලන්", "වවුලන්", "වී පුෂ්ප සුළඟින් පරාගණය වේ."),
    q("නෙළුම් ඵලයේ ස්පොන්ජි වැනි කේතුකාකාර පුෂ්පාසනය වැදගත් වන්නේ කුමක් සඳහාද?", "ජලය මත පාවී බීජ ව්‍යාප්ත කිරීමට", "කෘමීන් ආකර්ෂණය කිරීමට", "සුළඟින් පාවීමට", "සතුන්ගේ ඇඟේ ඇලීමට", "පුෂ්පාසනය පැසුණු පසු ජලයේ පාවී යමින් බීජ මුදා හරී."),
    q("සංයුක්ත පත්‍රයක් හා සරල පත්‍රයක් හඳුනා ගැනීමට පත්‍ර වෘන්තයේ පාදයේ පිහිටීම පරීක්ෂා කළ යුතු ව්‍යුහය කුමක්ද?", "කක්ෂීය අංකුරය", "පත්‍ර දාරය", "පත්‍ර අග්‍රය", "මැද නාරටිය", "සංයුක්ත පත්‍රයක පත්‍රිකා පාදයේ කක්ෂීය අංකුර නොමැත."),
    q("පළතුරු සලාදයක් සාදා තබන විට ඇපල් හෝ කෙසෙල් පෙති දුඹුරු පැහැ ගැන්වීම වැළැක්වීමට දෙහි යුෂ එක් කිරීමෙන් සිදුවන්නේ කුමක්ද?", "එන්සයිම ක්‍රියාව වැළැක්වීම", "විටමින් C සැපයීම සිදු කිරීම", "සීනි දියකර ඉවත් කර දැමීම", "පිෂ්ඨය සාදා සංචිත කිරීම", "ආම්ලිකතාව නිසා ඔක්සිකාරක එන්සයිම අක්‍රිය වේ."),
    q("ශාක පටකයක සෛල තුළ ජල පීඩනය අඩු වූ විට ශාක පත්‍ර එල්ලා වැටීම හඳුන්වන්නේ කෙසේද?", "මැලවීම (Wilting)", "ප්‍රරෝහණය", "අවශෝෂණය", "ශූන වීම", "උත්ස්වේදනය අවශෝෂණයට වඩා වැඩි වූ විට ශාකය මැලවේ."),
    q("සපුෂ්ප ශාකයක ද්විත්ව සංසේචනයේදී ප්‍රධාන වශයෙන් සෑදෙන ව්‍යුහ දෙක මොනවාද?", "යුක්තාණුව හා භ්‍රෑණ පෝෂ න්‍යෂ්ටිය", "පරාගය හා රේණුව", "බීජාවරණය හා ඵලාවරණය", "මූල කේශය හා කඳ", "යුක්තාණුව භ්‍රෑණය බවටත් ත්‍රිගුණ න්‍යෂ්ටිය භ්‍රෑණ පෝෂය බවටත් පත්වේ."),
    q("ශාක පත්‍රයක පහළට නොවැටී තිරස්ව පැවතීම සඳහා යාන්ත්‍රික ආධාර සපයන පත්‍ර කොටස කුමක්ද?", "පත්‍ර නාරටි ජාලය", "පාලක සෛල", "උච්චර්මය", "පත්‍ර රන්ධ්‍ර", "නාරටි තුළ සෛලම, ෆ්ලෝයම හා දෘඪස්තර තන්තු අඩංගු වේ."),
    q("එක් ශාකයක පරාග එම ශාකයේම වෙනත් පුෂ්පයක කලංකයේ තැන්පත් වීම කුමන පරාගණයක්ද?", "ස්ව-පරාගණය", "පර පරාගණය", "ජල පරාගණය", "වායු පරාගණය", "එකම ශාකය තුළ සිදුවන පරාගණය ස්ව-පරාගණය ලෙස සැලකේ."),
    q("කුණු මස් ගඳ විහිදුවන රැෆ්ලීසියා වැනි පුෂ්ප පරාගණය කිරීමට ආකර්ෂණය වන ජීවීන් කවුද?", "මැස්සන් හා කුරුමිණියන්", "මීමැස්සන්", "සමනලුන්", "හමින් කුරුල්ලන්", "දුගඳ හමන පුෂ්ප මැස්සන් ගෙන්වා ගනී."),
    q("රාත්‍රී කාලයේදී පිපෙන සුදු පැහැති සුවඳවත් කඩුපුල් හා සේපාලිකා වැනි පුෂ්ප පරාගණය කරන ප්‍රධාන සත්වයා කවුද?", "රාත්‍රී සලබයන් හා වවුලන්", "මීමැස්සන්", "මොනරුන්", "කූඹින්", "සුදු පැහැය රාත්‍රියේදී පහසුවෙන් දැකිය හැකි වේ."),
    q("වැලිස්නේරියා වැනි ජලජ ශාකවල පරාගණය සිදුවන ප්‍රධාන මාධ්‍යය කුමක්ද?", "ජලය", "සුළඟ", "කෘමීන්", "පක්ෂීන්", "පුරුෂ පුෂ්ප ජල මතුපිට පාවී විත් ස්ත්‍රී පුෂ්ප හමු වේ."),
    q("සංසේචනයෙන් පසු පුෂ්පයේ මණි පත්‍ර, දළ පත්‍ර සහ රේණුවලට සාමාන්‍යයෙන් කුමක් සිදුවේද?", "වියළී හැලී යයි", "බීජ බවට පත්වේ", "ඵලාවරණය සාදයි", "මුල් බවට පත්වේ", "වම්බටු හා තක්කාලි වැනි සමහර ඵලවල මණි පත්‍ර චිරස්ථායීව ඉතිරි වේ."),
    q("බෝග මාරුවේදී රනිල කුලයේ ශාක වගා කිරීමෙන් පස සරු වන්නේ කෙසේද?", "වායුගෝලීය නයිට්‍රජන් තිර කිරීමෙන්", "පසේ ජල ධාරිතාව වැඩි කිරීමෙන්", "පසේ ආම්ලිකතාව ඉහළ දැමීමෙන්", "පොස්පරස් ඛනිජ නිපදවීමෙන්", "රයිසෝබියම් බැක්ටීරියා නයිට්‍රේට සාදයි."),
    q("බඩඉරිඟු බීජයක තිබෙන එකම බීජ පත්‍රය හඳුන්වන්නේ කුමන නමින්ද?", "වරුතිකාව (Scutellum)", "ප්‍රරෝහ කොපුව", "මූල කොපුව", "භ්‍රෑණ පෝෂය", "ඒකබීජ පත්‍රී බීජවල එක් බීජ පත්‍රයක් පමණක් පවතී."),
    q("කඩොලාන ශාකවල බීජ මව් ශාකය මත තිබියදීම ප්‍රරෝහණය වීමේ සුවිශේෂී ක්‍රියාවලිය කුමක්ද?", "ජලාබුජ ප්‍රරෝහණය (Vivipary)", "සුප්තතාව", "අනිෂේක ඵලතාව", "වර්ධක ප්‍රචාරණය", "රයිසොෆෝරා බීජ මඩේ කෙළින්ම සිටුවීමට මෙය උපකාරී වේ."),
    q("පත්‍රයක නිපදවෙන ආහාර ෆ්ලෝයමය ඔස්සේ ඉවත් නොවී රැස්වුවහොත් ප්‍රභාසංස්ලේෂණයට කුමක් වේද?", "ප්‍රභාසංස්ලේෂණ සීඝ්‍රතාව පහළ බසී", "උත්ස්වේදනය නවතී", "මුල් කුණු වේ", "කඳ පුපුරා යයි", "නිෂ්පාදන ඉවත් නොවීම ප්‍රතික්‍රියා සීඝ්‍රතාව අඩාල කරයි."),
    q("කුරුඳු හා කරාබුනැටි වැනි ශාකවලින් වාෂ්ප ආසවනයෙන් වෙන් කරගන්නා වටිනා සංයෝග මොනවාද?", "සගන්ධ තෙල් (Essential oils)", "සෙලියුලෝස්", "ග්ලූකෝස්", "ඛනිජ අයන", "සගන්ධ තෙල් ඖෂධ හා සුවඳ විලවුන් සඳහා යොදා ගනී."),
    q("පත්‍රයක යටි පෘෂ්ඨයේ වැස්ලින් ආලේප කළහොත් ශාකයට සිදුවන ප්‍රධාන බලපෑම කුමක්ද?", "රන්ධ්‍ර වැසී වායු හුවමාරුව හා උත්ස්වේදනය අවම වීම", "ප්‍රභාසංස්ලේෂණය වේගවත් වීම", "හරිතප්‍රද වැඩිවීම", "පත්‍රයේ වර්ධනය දෙගුණ වීම", "බොහෝ රන්ධ්‍ර පිහිටන්නේ යටි පෘෂ්ඨයේ බැවිනි."),
    q("අලුතින් බෙදෙන ශාක සෛලවල මධ්‍ය සූත්‍රිකාව තැනීමට අත්‍යවශ්‍ය වන ඛනිජ අයනය කුමක්ද?", "කැල්සියම් (Ca²⁺)", "සෝඩියම්", "ක්ලෝරයිඩ්", "යකඩ", "සෛල බිත්ති එකිනෙක සම්බන්ධ කරන කැල්සියම් පෙක්ටේට් සාදයි."),
    q("ශාකයක අග්‍රස්ථ අංකුරය නිසා පාර්ශ්වික අංකුර වර්ධනය යටපත් වීම හඳුන්වන්නේ කෙසේද?", "අග්‍රස්ථ ප්‍රමුඛතාවය", "ධන ප්‍රකාශවර්තනය", "ද්විතීයික වර්ධනය", "පත්‍ර අකාලයේ හැලීම", "අග්‍රයේ නිපදවෙන ඔක්සීන් පාර්ශ්වික අංකුර වර්ධනය පාලනය කරයි."),
    q("තේ වගාවේදී දළු වැඩි කර ගැනීමට අග්‍රස්ථ කප්පාදු කිරීමෙන් සිදුවන්නේ කුමක්ද?", "පාර්ශ්වික අංකුර වර්ධනය උත්තේජනය වීම", "මුල් දිගු වීම", "පුෂ්ප පිපීම වැඩි වීම", "උත්ස්වේදනය නැවතීම", "පඳුර පළලට වැඩී අලුත් අතු රාශියක් හටගනී."),
    q("ප්‍රකාශාවර්තීතාව (Photoperiodism) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දිවා කාල පරාසය මත මල් හට ගැනීම පාලනය වීම", "ජලය හමුවේ මුල් පද්ධතිය පහළට වර්ධනය වීම", "රාත්‍රියේදී ශාක පත්‍ර සංකෝචනය වී වැසීම", "අහිතකර කාලගුණයකදී බීජ නිද්‍රාශීලීව පැවතීම", "සමහර ශාක කෙටි දින ශාක ද සමහර ශාක දිගු දින ශාක ද වේ."),
    q("සෛලම නාලවල ජලය ඉහළට නැගීමේදී කේශාකර්ෂණ බලය වැඩි වීමට හේතුව කුමක්ද?", "නාල ඉතා සිහින් හා පටු වීම", "නාල ඉතා පළල් වීම", "හරස් බිත්ති තිබීම", "වාතය පිරී තිබීම", "නාලයේ විෂ්කම්භය කුඩා වන තරමට කේශාකර්ෂණ උස වැඩි වේ."),
    q("උත්ස්වේදන ඇදුම ක්‍රියාත්මක වීමට මූලික වන බාහිර ශක්ති ප්‍රභවය කුමක්ද?", "සූර්ය තාප ශක්තිය", "පාංශු බැක්ටීරියා", "චුම්භක ක්ෂේත්‍රය", "ගුරුත්වාකර්ෂණය", "සූර්ය තාපය පත්‍රවලින් ජලය වාෂ්ප කර චූෂණයක් ඇති කරයි."),
    q("හයිඩ්‍රිල්ලා පරීක්ෂණයේදී ජලයට NaHCO₃ එක් කිරීමෙන් ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "ප්‍රභාසංස්ලේෂණය සඳහා ද්‍රාව්‍ය CO₂ සැපයීම", "ජලය ආම්ලික කිරීම", "ඔක්සිජන් අවශෝෂණය", "හරිතප්‍රද දිය කිරීම", "CO₂ සැපයුම වැඩි වූ විට පිටවන O₂ බුබුළු ගණන වැඩි වේ."),
    q("අංකුර බද්ධයේදී (Budding) ග්‍රාහකයාගේ පොත්තේ සාදන T හෝ H කැපුම තුළ රඳවන්නේ කුමක්ද?", "කක්ෂීය අංකුරයක් සහිත පොතු කැබැල්ලක්", "පස යටින් ගත් මුල් කැබැල්ලක්", "පරිණත වූ පත්‍ර නටුවක්", "ප්‍රරෝහණය වූ බීජයක්", "අනුජයේ ලක්ෂණ සහිත නව ගසක් ඉන් හට ගනී."),
    q("බද්ධ සන්ධිය පොලිතීන් පටියකින් ආවරණය කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "ජලය හා විෂබීජ ඇතුළුවීම වැළැක්වීමට", "සූර්යාලෝකය සෘජුව ලබා ගැනීමට", "පොත්ත ඉක්මනින් දිරාපත් කිරීමට", "වැඩි ඔක්සිජන් ප්‍රමාණයක් දීමට", "කැම්බියම් පටක එකට හාවී සම්බන්ධ වන තෙක් ආරක්ෂාව සැපයේ."),
    q("දඬු කැබැල්ලක් සිටුවීමේදී පහළ කෙළවර ඇලයට කැපීමෙන් සිදුවන්නේ කුමක්ද?", "මුල් ඇදීමට හා ජලය උරා ගැනීමට වැඩි පෘෂ්ඨයක් ලැබීම", "පත්‍ර ඉක්මනින් හැලීම", "පුෂ්ප පිපීම නැවතීම", "මැලවීම වේගවත් වීම", "වැඩි කැම්බියම් ස්තරයක් පසට නිරාවරණය වේ."),
    q("ශාක කඳේ හරස්කඩක වාර්ෂික වළලු (Annual rings) දැකිය හැකි පටකය කුමක්ද?", "ද්විතීයික සෛලමය", "ප්‍රාථමික ෆ්ලෝයමය", "උච්චර්මය", "මූල කොපුව", "වසරක වර්ධනයක් එක් වළල්ලකින් නිරූපණය වන නිසා ගසේ වයස නිර්ණය කළ හැක."),
    q("පැරණි ගසක කඳ මැද ඇති තද දුඹුරු පැහැති අරටුවේ (Heartwood) ප්‍රධාන කාර්යය කුමක්ද?", "ගසට යාන්ත්‍රික ශක්තිය සැපයීම", "ප්‍රභාසංස්ලේෂණය කිරීම", "සුක්‍රෝස් පරිවහනය කිරීම", "පරාග නිපදවීම", "පිටතින් පිහිටි එළය (Sapwood) මගින් ජලය ඉහළට ගෙන යයි."),
    q("ශාක පත්‍රයක් වියළී හැලීමට පෙර එම පත්‍රයෙන් ශාකය වෙත නැවත අවශෝෂණය කර ගන්නේ කුමක්ද?", "නයිට්‍රජන් හා මැග්නීසියම් අයන", "සෙලියුලෝස් හා පෙක්ටින් තන්තු", "ලිග්නින් සහ සුබෙරින් කොටස්", "සිලිකා සහ කැල්සියම් ඔක්සයිඩ්", "පැරණි පත්‍ර කහ වන්නේ හරිතප්‍රද බිඳී මැග්නීසියම් ඉවත් වන බැවිනි."),
    q("කෘමි පරාගිත පුෂ්පවල කලංකය සුළං පරාගිත පුෂ්පවලට වඩා වෙනස් වන්නේ කෙසේද?", "කුඩා හා ඇලෙන සුළු වීම", "ඉතා විශාල පිහාටු වැනි වීම", "පුෂ්පයෙන් පිටතට දිගට එල්ලී තිබීම", "වියළි හා සිනිඳු වීම", "කෘමියාගේ සිරුරේ තැවරුණු පරාග ඇලෙන සුළු කලංකයේ රැඳේ."),
    q("මෑ හෝ බෝංචි බීජයක පොත්ත මත ඇති සිහින් පැල්ලමක් වැනි කළල නාභිය (Hilum) යනු කුමක්ද?", "බීජය කරලේ බිත්තියට සවි වී තිබූ ස්ථානය", "මූලාංකුරය පිටවන සිදුර", "පත්‍ර වැවෙන ස්ථානය", "හරිතප්‍රද තැන්පත් තැන", "ඊට ආසන්නව කුඩා අණ්ඩ ද්වාරය පිහිටා ඇත."),
    q("වී ඇට ගබඩා කිරීමට පෙර හොඳින් අව්වේ වියළන්නේ ඇයි?", "තෙතමනය අඩු කර පුස් බැඳීම වැළැක්වීමට", "ධාන්‍යවල බර හා ඝනත්වය වැඩි කිරීමට", "නව හරිතලව සෑදීම උත්තේජනය කිරීමට", "අභ්‍යන්තර ඔක්සිජන් ඉවත් කර දැමීමට", "තෙතමනය අඩු විට එන්සයිම හා දිලීර ක්‍රියාකාරිත්වය නවතී."),
    q("වියළි බෝංචි ඇටයක් ජලයේ දැමූ විට බීජාවරණය ඉදිමී පිපීමේ ආරම්භක ක්‍රියාවලිය කුමක්ද?", "අන්තශ්චූෂණය (Imbibition)", "විසරණය", "උත්ස්වේදනය", "දුස්ස්වභාවීකරණය", "බීජය තුළට ජලය ඇතුළු වී එන්සයිම සක්‍රිය කරයි."),
    q("රසායනාගාරයේදී හරිතප්‍රද දිය කිරීම සඳහා පත්‍රය තැම්බීමට භාවිත කරන ප්‍රධාන ද්‍රාවකය කුමක්ද?", "එතනෝල් (මෙතිලේටඩ් ස්ප්‍රීතු)", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "ආස්‍රැත ජලය", "සෝඩියම් ක්ලෝරයිඩ්", "එතනෝල් හරිතප්‍රද දිය කර පත්‍රය අවර්ණ කරයි."),
    q("කැල්වින් චක්‍රය සඳහා අවශ්‍ය වන ශක්තිය (ATP) සහ ඔක්සිහාරක (NADPH) සැපයෙන්නේ කුමන ප්‍රතික්‍රියාවෙන්ද?", "ආලෝක ප්‍රතික්‍රියාවෙන්", "නිර්වායු ශ්වසනයෙන්", "උත්ස්වේදන ක්‍රියාවෙන්", "සෛලීය විසරණයෙන්", "ආලෝක ප්‍රතික්‍රියාවේ ඵල අඳුරු ප්‍රතික්‍රියාවට යොදා ගැනේ."),
    q("සෙවණේ වැඩෙන ශාක පත්‍ර හිරු එළියේ වැඩෙන පත්‍රවලට වඩා තුනී හා පළල් වන්නේ ඇයි?", "අඩු ආලෝකය උපරිම ලෙස අල්ලා ගැනීමට", "වැඩි ජලය ඉවත් කිරීමට", "සුළඟට ඔරොත්තු දීමට", "පරාග විසුරුවා හැරීමට", "සෙවණ ශාකවල උපරිම කාර්යක්ෂමතාව සඳහා පත්‍ර පෘෂ්ඨය විශාලය."),
    q("පොල් මලක් ආවරණය කරන දැවමය පැහැති විශාල ආවරණය හඳුන්වන්නේ කෙසේද?", "හනස්ස (නිපත්‍ර කොපුව)", "මණිය", "මුකුටය", "පුෂ්පාසනය", "එය පුෂ්ප මංජරිය පොහොට්ටු කාලයේදී ආරක්ෂා කරයි."),
    q("දෙමුහුන් බෝග ප්‍රභේද (Hybrid varieties) කෘෂිකර්මාන්තයේදී වැඩිපුර භාවිත කිරීමට ප්‍රධාන හේතුව කුමක්ද?", "ඉහළ අස්වැන්නක් හා රෝගවලට ඔරොත්තු දීමේ හැකියාව", "පස හා ජලය අනවශ්‍ය වීම", "සූර්යාලෝකය නොමැතිව වැඩීම", "පොහොර භාවිතය ශුන්‍ය වීම", "වඩා හොඳ ලක්ෂණ සහිත මව් ශාක දෙකක් මුහුම් කිරීමෙන් නිපදවේ."),
    q("ශාක පත්‍රයක උඩු අපිචර්මයේ ප්‍රධාන ව්‍යුහමය ලක්ෂණය කුමක්ද?", "සෛල හිඩැස් නැතිව තදින් ඇසිරී තිබීම", "සෛල අතර විශාල වායු කුහර පිහිටීම", "හරිතලව විශාල සංඛ්‍යාවක් අඩංගු වීම", "ඝන ලිග්නින් ද්විතීයික බිත්ති පැවතීම", "ඇතුළත සෛල ආරක්ෂා කිරීම හා විනිවිදභාවය මෙහි ලක්ෂණයයි."),
    q("කෙසෙල් වැනි ශාකයක ගුණාත්මකභාවය නොවෙනස්ව පවත්වා ගෙන බෝ කිරීමට වඩාත් සුදුසු ප්‍රචාරණ ක්‍රමය කුමක්ද?", "මෝරියන් මගින් වර්ධක ප්‍රචාරණය", "බීජ රෝපණය", "පර පරාගණය", "බීජාණු මගින්", "වර්ධක ප්‍රචාරණය මඟින් සර්වසම දුහිතෘ ශාක ලැබේ."),
    q("කනේරු වැනි වියළි කලාපීය ශාක පත්‍රවල උත්ස්වේදනය අඩු කිරීමට ඇති අනුවර්තනය කුමක්ද?", "ගිලුණු පත්‍ර රන්ධ්‍ර සහ රෝම පිහිටීම", "ඉතා තුනී පත්‍ර තිබීම", "උච්චර්මය නොතිබීම", "රන්ධ්‍ර උඩු පෘෂ්ඨයේ පිහිටීම", "වායු ධාරා සෘජුව රන්ධ්‍ර මත ගැටීම මෙමඟින් වළකී."),
    q("ශාක මුල් පසේ ගැඹුරට හා පුළුල්ව විහිදී යාමෙන් ශාකයට සැලසෙන ප්‍රධාන වාසි දෙක මොනවාද?", "ශක්තිමත් සවිවීම හා ජලය-ඛනිජ අවශෝෂණය", "ප්‍රභාසංස්ලේෂණය හා පරාගණය", "බීජ ව්‍යාප්තිය හා ශ්වසනය", "උත්ස්වේදනය හා බිංදුදය", "සමහර මුල් ආහාර සංචිත කිරීමට ද දායක වේ."),
    q("ශාකයකට ප්‍රමාණවත් තරම් ආලෝකය ලැබුණද ප්‍රභාසංස්ලේෂණ වේගය වැඩි නොවී නියත වීමට හේතුව කුමක්ද?", "වෙනත් සාධකයක් සීමාකාරී වීම", "හරිතප්‍රද අණු අතුරුදහන් වීම", "ශෛලම වාහිනී සම්පූර්ණ අවහිර වීම", "මුල් පසෙන් ගැලවී ඉවත් වීම", "සීමාකාරී සාධක නියමය මගින් මෙය පැහැදිලි කෙරේ."),
    q("ශාකවල ඛනිජ පෝෂණය අධ්‍යයනයේදී පස නොමැතිව පෝෂක ද්‍රාවණයක ශාක වගා කිරීමේ ක්‍රමය කුමක්ද?", "ජල රෝපණය (Hydroponics)", "පටක රෝපණය", "බද්ධ කිරීම", "අතු බැඳීම", "විශේෂිත ඛනිජ ඌනතා ලක්ෂණ පරීක්ෂා කිරීමට ද මෙය භාවිත කෙරේ."),
    q("ජල රෝපණයේදී පෝෂක ද්‍රාවණය තුළට නිරන්තරයෙන් වාතය බුබුලනය කරන්නේ ඇයි?", "ස්වායු ශ්වසනයට ඔක්සිජන් සැපයීමට", "ද්‍රාවණය වේගයෙන් සිසිල් කිරීමට", "හරිතප්‍රද වර්ණක සංශ්ලේෂණයට", "පෝෂක ද්‍රාවණය කැටි ගැසීමට", "ඔක්සිජන් නොමැති වුවහොත් මුල් කුණු වී මිය යයි."),
    q("කළු පොලිතීන්වලින් ජල රෝපණ භාජනය ආවරණය කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "ද්‍රාවණයේ ඇල්ගී වර්ධනය වැළැක්වීම", "පෝෂක ජලය ක්ෂණිකව රත් කිරීම", "මුල්වල ප්‍රභාසංස්ලේෂණය වැඩිකිරීම", "කාබන් ඩයොක්සයිඩ් රඳවා තැබීම", "ආලෝකය නොලැබෙන විට ඇල්ගී බෝ නොවන අතර පෝෂක මුල්වලට පමණක් ලැබේ."),
    q("සපුෂ්ප ශාකවල ඵලයක් තුළ කිසිදු බීජයක් නොමැතිව වර්ධනය වීමේ ස්වාභාවික හෝ කෘත්‍රිම සංසිද්ධිය කුමක්ද?", "අනිෂේක ඵලතාව (Parthenocarpy)", "ජලාබුජ ප්‍රරෝහණය", "පරාගණය", "සුප්තතාව", "කෙසෙල් හා අන්නාසි වැනි ඵල මීට උදාහරණ වේ."),
    q("ශාක පටක රෝපණයේදී වගා කරනු ලබන කුඩා ශාක කොටස හඳුන්වන්නේ කුමන නමින්ද?", "ප්‍රචාරක කොටස (Explant)", "ග්‍රාහකය", "වරුතිකාව", "අණ්ඩ ද්වාරය", "ජීවානුහරණය කළ මේ කොටසින් කැලසය (Callus) හට ගනී."),
    q("මෑ පැළයක් වැනි ශාකයක සමතුලිතව සිදු වන ප්‍රභාසංස්ලේෂණය හා ශ්වසනය යන දෙකෙහි සීඝ්‍රතා සමාන වන අවස්ථාව කුමක්ද?", "හානිපූරණ ලක්ෂ්‍යය", "සන්තෘප්ත උෂ්ණත්වය", "සීමාකාරී සාන්ද්‍රණය", "ප්‍රතිපූරණ අවධිය", "මෙම අවස්ථාවේදී ශාකයෙන් පිටතට ශුද්ධ වායු හුවමාරුවක් සිදු නොවේ.")
  )
}
